		example: "แข็ง",
	},
	{
		vowel: "โ-ะ",
		openForm: "โ-ะ",
		withFinalForm: "--",
		example: "กฎ",
	},
	{
		vowel: "เ-าะ",
		openForm: "เ-าะ",
		withFinalForm: "-็อ-",
		example: "น็อต",
	},
	{
		vowel: "เ-อ",
		openForm: "เ-อ",
		withFinalForm: "เ-ิ-",
		example: "เดิน",
		exceptions: [
			{
				finalConsonant: "ย",
				form: "เ-ย",
				example: "เลย",
				note: "before a final ย the อ drops and no สระ อิ is written",
			},
		],
	},
	{
		vowel: "เ-อะ",
