13	
14	export type ConversionState = "unconverted" | "converted" | "failed";
15	
16	export interface ConversionResult {
17		state: ConversionState;
18		paiboon: string | null;
19		reason?: string;
20	}
21	
22	const TONE_MARKS: Record<string, ToneValue> = {
23		"̀": "low", // grave
24		"́": "high", // acute
25		"̂": "falling", // circumflex
26		"̌": "rising", // caron
27	};
28	const TONE_TO_MARK: Record<ToneValue, string> = {
