30		low: "̀",
31		high: "́",
32		falling: "̂",
33		rising: "̌",
34	};
35	const COMBINING_MARKS = new Set(Object.keys(TONE_MARKS));
36	
37	const IPA_MARKER_CHARS = new Set("ʰʔɕŋɯɛɔɤəʉː");
38	const ALLOWED_CHARS = new Set([
39		..."abcdefghijklmnopqrstuvwxyz ʰʔɕŋɯɛɔɤəʉː'-",
40		...COMBINING_MARKS,
41		..."àáâǎèéêěìíîǐòóôǒùúûǔ",
42	]);
43	
44	const ONSET_MAP: Record<string, string> = {
45		p: "bp",
46		t: "dt",
47		k: "g",
48		tɕ: "j",
49		pʰ: "ph",
50		tʰ: "th",
51		kʰ: "kh",
